{"file_text": "<nav aria-label="Application progress">
    <div class="step-bar">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var step = i + 1;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            <div class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "")"
                 @onclick="() => HandleClick(step)"
                 role="@(isClickable ? "button" : null)"
                 style="@(isClickable ? "cursor:pointer" : "")">
                @if (i > 0)
                {
                    <div class="step-connector @(CompletedSteps.Contains(step - 1) ? "done" : "")"></div>
                }
                <div class="step-circle">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <div class="step-label">@Steps[i]</div>
            </div>
        }
    </div>
</nav>

@code {
    private static readonly string[] Steps =
