+    <h4 class="mb-3">Personal Information</h4>
+
+    @if (!string.IsNullOrEmpty(_errorMessage))
+    {
+        <div class="alert alert-danger">@_errorMessage</div>
+    }
+
+    <div class="row g-3">
+        <div class="col-md-6">
+            <label class="form-label">Full Name <span class="text-danger">*</span></label>
+            <input class="form-control @FieldClass(Model.FullName)"
+                   @bind="Model.FullName" @bind:event="oninput" />
+            @if (_validated && string.IsNullOrWhiteSpace(Model.FullName))
+            {
+                <div class="invalid-feedback d-block">Full name is required.</div>
+            }
+        </div>
+        <div class="col-md-6">
+            <label class="form-label">Email <span class="text-danger">*</span></label>
+            <input type="email" class="form-control @FieldClass(Model.Email)"
+                   @bind="Model.Email" @bind:event="oninput" />
+            @if (_validated && string.IsNullOrWhiteSpace(Model.Email))
+            {
+                <div class="invalid-feedback d-block">Email is required.</div>
+            }
+        </div>
+        <div class="col-md-6">
+            <label class="form-label">Phone <span class="text-danger">*</span></label>
+            <input type="tel" class="form-control @FieldClass(Model.Phone)"
+                   @bind="Model.Phone" @bind:event="oninput" />
+            @if (_validated && string.IsNullOrWhiteSpace(Model.Phone))
+            {
+                <div class="invalid-feedback d-block">Phone number is required.</div>
+            }
+        </div>
+        <div class="col-md-6">
+            <label class="form-label">Address <span class="text-danger">*</span></label>
+            <input class="form-control @FieldClass(Model.Address)"
+                   @bind="Model.Address" @bind:event="oninput" />
+            @if (_validated && string.IsNullOrWhiteSpace(Model.Address))
+            {
+                <div class="invalid-feedback d-block">Address is required.</div>
+            }
+        </div>
+    </div>
+
+    <div class="mt-4 d-flex justify-content-end">
+        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
+            @if (_isValidating)
+            {
+                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+            }
+            Next
+        </button>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+
+    private bool _validated;
+    private bool _isValidating;
+    private string? _errorMessage;
+
+    private async Task HandleNext()
+    {
+        _validated = true;
+        _errorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(Model.FullName) ||
+            string.IsNullOrWhiteSpace(Model.Email) ||
+            string.IsNullOrWhiteSpace(Model.Phone) ||
+            string.IsNullOrWhiteSpace(Model.Address))
+        {
+            return;
+        }
+
+        _isValidating = true;
+        try
+        {
+            var isEmailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
+            if (!isEmailValid)
+            {
+                _errorMessage = "The email address could not be validated. Please check and try again.";
+                return;
+            }
+
+            await OnNext.InvokeAsync();
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    private string FieldClass(string value) =>
+        _validated && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";
+}
