@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (_submitted)
    {
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 4rem; color: #198754;">✓</div>
            <h2>Application Submitted!</h2>
            <p class="lead text-muted">Your application has been received successfully.</p>
            <p>Your application ID is: <strong class="fs-4">@_applicationId</strong></p>
            <a href="/apply" class="btn btn-outline-primary mt-3" data-enhance-nav="false">Submit Another Application</a>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personalInfo"
                                  OnNext="AdvanceStep" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="AdvanceStep"
                                 OnBack="StepBack" />
                break;
            case 3:
                <ReferencesStep References="_references"
                                OnNext="AdvanceStep"
                                OnBack="StepBack" />
                break;
            case 4:
                <CoverLetterStep Model="_coverLetter"
                                 OnNext="AdvanceStep"
                                 OnBack="StepBack" />
                break;
            case 5:
                <ReviewStep PersonalInfo="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            IsSubmitting="_isSubmitting"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="StepBack" />
                break;
        }
    }
</div>

@code {
    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];
    private bool _submitted;
    private int _applicationId;
    private bool _isSubmitting;

    // Form state — mutable models passed by reference to step components
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private readonly CoverLetterModel _coverLetter = new();

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void AdvanceStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void StepBack()
    {
        if (_currentStep > 1)
        {
            _currentStep--;
        }
    }

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        try
        {
            var application = BuildApplication();
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _completedSteps.Add(5);
            _submitted = true;
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private JobApplication BuildApplication()
    {
        var personal = new PersonalInfo(
            _personalInfo.FullName, _personalInfo.Email,
            _personalInfo.Phone, _personalInfo.Address);

        var entries = _workEntries.Select(e => new WorkEntry(
            e.Company, e.Title,
            e.StartDate ?? DateTime.MinValue,
            e.IsCurrent ? null : e.EndDate,
            e.Description)).ToList();

        var refs = _references
            .Where(r => !string.IsNullOrWhiteSpace(r.Name))
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        return new JobApplication(personal, new WorkHistory(entries), refs, _coverLetter.Text);
    }
}

